{
  "title": "Spaghetti Carbonara",
  "description": "Classic Roman pasta with eggs, cheese and pancetta.",
  "ingredients": [
    {
      "name": "Spaghetti",
      "quantity": "200 g"
    },
    {
      "name": "Pancetta",
      "quantity": "100 g"
    },
    {
      "name": "Eggs",
      "quantity": "2"
    },
    {
      "name": "Pecorino Romano",
      "quantity": "50 g"
    }
  ],
  "instructions": [
    "Boil the spaghetti in salted water until al dente.",
    "Fry the pancetta until crisp.",
    "Whisk eggs with grated cheese.",
    "Toss hot pasta with pancetta, then stir in the egg mixture off the heat."
  ],
  "prepTime": 10,
  "cookTime": 15,
  "servings": 2,
  "difficulty": "medium",
  "category": "italian"
}

